package com.thangit.boardinghouse.service.integration;

import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import jakarta.validation.constraints.*;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.json.JsonMapper;

@Service
public class IntegrationCenter {
    public static final List<String> KINDS=List.of("EMAIL","ZALO","WEB_PUSH","PAYMENT","AI");
    public static final Map<String,Set<String>> FIELDS=Map.of(
        "EMAIL",Set.of("host","port","username","fromEmail","fromName","tlsMode","authentication"),
        "ZALO",Set.of("oaId","oaName","appId","redirectUri","templateMappings","templateParameters"),
        "WEB_PUSH",Set.of("publicKey","subject"),
        "PAYMENT",Set.of("cashEnabled","bankTransferEnabled","bankName","bankBin","qrEnabled","accountName","accountNumber","transferContent","vnpayEnabled","tmnCode","vnpayReturnUrl","vnpayIpnUrl","momoEnabled","partnerCode","momoRedirectUrl","momoIpnUrl"),
        "AI",Set.of("model","faqEnabled","messageSuggestionsEnabled","anomalyEnabled","forecastEnabled","monthlyLimit"));
    public static final Map<String,Set<String>> SECRETS=Map.of("EMAIL",Set.of("PASSWORD"),"ZALO",Set.of("ACCESS_TOKEN","REFRESH_TOKEN","APP_SECRET","OA_SECRET"),"WEB_PUSH",Set.of("PRIVATE_KEY"),"PAYMENT",Set.of("VNPAY_HASH_KEY","MOMO_ACCESS_KEY","MOMO_SECRET_KEY"),"AI",Set.of("API_KEY"));
    public record Save(@NotBlank String provider,@NotBlank String environment,boolean enabled,@NotNull Map<String,Object> settings,Map<String,String> secrets,@Min(0) long version){@Override public String toString(){return "Integration configuration [credentials redacted]";}}
    public record TestRequest(@Size(max=255) String recipient,@Size(max=60) String templateId,Map<String,String> parameters){}
    public record Config(long owner,String kind,String provider,String environment,boolean enabled,Map<String,Object> settings,String status,long version){public String text(String key){return Objects.toString(settings.get(key),"");}public boolean bool(String key){return Boolean.TRUE.equals(settings.get(key));}}
    final JdbcClient db;final IntegrationVault vault;final IntegrationAdapters adapters;final JsonMapper json;final com.thangit.boardinghouse.service.AdminSettingService settings;final IntegrationRuleInstaller rules;
    public IntegrationCenter(JdbcClient db,IntegrationVault vault,IntegrationAdapters adapters,JsonMapper json,com.thangit.boardinghouse.service.AdminSettingService settings,IntegrationRuleInstaller rules){this.db=db;this.vault=vault;this.adapters=adapters;this.json=json;this.settings=settings;this.rules=rules;}
    public static AuthException invalid(String code){return new AuthException(HttpStatus.BAD_REQUEST,code,"Cấu hình hoặc thao tác tích hợp chưa hợp lệ. Mã: "+code);}
    public long owner(AuthenticatedUser actor){if(actor==null||actor.activeRole()!=RoleCode.OWNER)throw new AuthException(HttpStatus.FORBIDDEN,"INTEGRATION_ACCESS_DENIED","Chỉ chủ nhà được cấu hình tích hợp thuộc phạm vi của mình.");if(db.sql("SELECT COUNT(*) FROM users WHERE id=:id AND status='ACTIVE'").param("id",actor.id()).query(Long.class).single()!=1)throw invalid("INTEGRATION_ACTOR_INACTIVE");return actor.id();}
    void kind(String kind){if(!KINDS.contains(kind))throw invalid("INTEGRATION_KIND_INVALID");}
    public Config config(long owner,String kind){kind(kind);var rows=db.sql("SELECT * FROM integration_configs WHERE owner_id=:owner AND kind=:kind").param("owner",owner).param("kind",kind).query().listOfRows();if(rows.isEmpty())return new Config(owner,kind,Map.of("EMAIL","SMTP","ZALO","ZBS","WEB_PUSH","VAPID","PAYMENT","MANUAL","AI","RULE_BASED").get(kind),"TEST",false,Map.of(),"NOT_CONFIGURED",0);var row=rows.getFirst();return new Config(owner,kind,row.get("provider").toString(),row.get("environment").toString(),Boolean.TRUE.equals(row.get("enabled")),parse(row.get("settings")),row.get("status").toString(),((Number)row.get("version")).longValue());}
    @SuppressWarnings("unchecked") Map<String,Object> parse(Object text){try{return text==null?Map.of():json.readValue(text.toString(),Map.class);}catch(Exception e){throw new IllegalStateException("Integration metadata unreadable");}}
    public Map<String,Object> view(long owner,String kind){var c=config(owner,kind);var out=new LinkedHashMap<String,Object>();out.put("kind",kind);out.put("provider",c.provider());out.put("environment",c.environment());out.put("enabled",c.enabled());out.put("settings",c.settings());out.put("version",c.version());out.put("status",c.status());out.put("secretStoreWritable",vault.writable());var secretStates=new TreeMap<String,Boolean>();for(String name:SECRETS.get(kind))secretStates.put(name,vault.present(owner,kind,name));out.put("secretsConfigured",secretStates);var rows=db.sql("SELECT last_checked_at,result_code,capabilities FROM integration_configs WHERE owner_id=:owner AND kind=:kind").param("owner",owner).param("kind",kind).query().listOfRows();if(!rows.isEmpty()){out.put("lastCheckedAt",rows.getFirst().get("last_checked_at"));out.put("resultCode",rows.getFirst().get("result_code"));out.put("capabilities",parse(rows.getFirst().get("capabilities")));}return out;}
    public List<Map<String,Object>> list(AuthenticatedUser actor){long owner=owner(actor);return KINDS.stream().map(kind->view(owner,kind)).toList();}
    public Map<String,Object> read(AuthenticatedUser actor,String kind){return view(owner(actor),kind);}
    @Transactional public Object disconnectZalo(AuthenticatedUser actor){long owner=owner(actor);db.sql("SELECT id FROM users WHERE id=:id FOR UPDATE").param("id",owner).query(Long.class).single();db.sql("DELETE FROM integration_credentials WHERE owner_id=:owner AND kind='ZALO'").param("owner",owner).update();db.sql("DELETE FROM integration_templates WHERE owner_id=:owner").param("owner",owner).update();db.sql("DELETE FROM integration_oauth_states WHERE owner_id=:owner").param("owner",owner).update();db.sql("UPDATE integration_configs SET enabled=FALSE,status='DISABLED',result_code='DISCONNECTED_LOCALLY',version=version+1 WHERE owner_id=:owner AND kind='ZALO'").param("owner",owner).update();return view(owner,"ZALO");}
    @Transactional public Map<String,Object> generateVapid(AuthenticatedUser actor){long owner=owner(actor);if(!vault.writable())throw invalid("SECRET_STORE_NOT_CONFIGURED");try{if(java.security.Security.getProvider("BC")==null)java.security.Security.addProvider(new org.bouncycastle.jce.provider.BouncyCastleProvider());var generator=java.security.KeyPairGenerator.getInstance("ECDH","BC");generator.initialize(new org.bouncycastle.jce.spec.ECNamedCurveGenParameterSpec("prime256v1"));var pair=generator.generateKeyPair();String publicKey=Base64.getUrlEncoder().withoutPadding().encodeToString(((org.bouncycastle.jce.interfaces.ECPublicKey)pair.getPublic()).getQ().getEncoded(false));byte[] raw=((org.bouncycastle.jce.interfaces.ECPrivateKey)pair.getPrivate()).getD().toByteArray();byte[] privateBytes=new byte[32];System.arraycopy(raw,Math.max(0,raw.length-32),privateBytes,Math.max(0,32-raw.length),Math.min(32,raw.length));String privateKey=Base64.getUrlEncoder().withoutPadding().encodeToString(privateBytes);var current=config(owner,"WEB_PUSH");var settings=new LinkedHashMap<>(current.settings());settings.put("publicKey",publicKey);settings.putIfAbsent("subject","mailto:"+db.sql("SELECT email FROM users WHERE id=:id").param("id",owner).query(String.class).single());var result=save(actor,"WEB_PUSH",new Save("VAPID",current.environment(),current.enabled(),settings,Map.of("PRIVATE_KEY",privateKey),current.version()));db.sql("UPDATE web_push_subscriptions SET enabled=FALSE,disabled_at=CURRENT_TIMESTAMP(6) WHERE owner_id=:owner").param("owner",owner).update();return result;}catch(com.thangit.boardinghouse.common.exception.AuthException e){throw e;}catch(Exception e){throw invalid("VAPID_GENERATION_FAILED");}}
    @Transactional public Map<String,Object> save(AuthenticatedUser actor,String kind,Save request){long owner=owner(actor);kind(kind);db.sql("SELECT id FROM users WHERE id=:id FOR UPDATE").param("id",owner).query(Long.class).single();if(!Set.of("DEV","TEST","PRODUCTION").contains(request.environment()))throw invalid("INTEGRATION_ENVIRONMENT_INVALID");if(!Map.of("EMAIL",Set.of("SMTP"),"ZALO",Set.of("ZBS"),"WEB_PUSH",Set.of("VAPID"),"PAYMENT",Set.of("MANUAL","VNPAY","MOMO"),"AI",Set.of("RULE_BASED","OPENAI","GEMINI")).get(kind).contains(request.provider()))throw invalid("INTEGRATION_PROVIDER_INVALID");if(!FIELDS.get(kind).containsAll(request.settings().keySet())||request.settings().size()>30)throw invalid("INTEGRATION_FIELD_REJECTED");for(Object value:request.settings().values())if(!(value instanceof String||value instanceof Boolean||value instanceof Number||value instanceof Map)||value.toString().length()>8000)throw invalid("INTEGRATION_VALUE_INVALID");var secrets=request.secrets()==null?Map.<String,String>of():request.secrets();if(kind.equals("PAYMENT")&&secrets.values().stream().anyMatch(value->value!=null&&!value.isBlank()))throw invalid("PAYMENT_CREDENTIAL_ENV_REQUIRED");if(!SECRETS.get(kind).containsAll(secrets.keySet()))throw invalid("INTEGRATION_CREDENTIAL_REJECTED");var current=config(owner,kind);if(current.version()!=request.version())throw new AuthException(HttpStatus.CONFLICT,"INTEGRATION_VERSION_CONFLICT","Cấu hình đã thay đổi, hãy tải lại.");if(kind.equals("PAYMENT")&&db.sql("SELECT COUNT(*) FROM gateway_sessions WHERE owner_id=:owner AND status IN ('CREATED','REQUESTING','PENDING') AND expires_at>CURRENT_TIMESTAMP").param("owner",owner).query(Long.class).single()>0)throw invalid("GATEWAY_CONFIGURATION_HAS_PENDING_PAYMENTS");for(var entry:secrets.entrySet())vault.write(owner,kind,entry.getKey(),entry.getValue());String status=request.enabled()?"CONFIGURED":"DISABLED";var candidate=new Config(owner,kind,request.provider(),request.environment(),request.enabled(),request.settings(),status,current.version());adapters.validate(candidate);if(request.enabled()&&!adapters.complete(candidate))status="NOT_CONFIGURED";
        int changed=db.sql("INSERT INTO integration_configs(owner_id,kind,provider,environment,enabled,settings,status,version) VALUES(:owner,:kind,:provider,:environment,:enabled,:settings,:status,1) ON DUPLICATE KEY UPDATE provider=IF(version=:version,:provider,provider),environment=IF(version=:version,:environment,environment),enabled=IF(version=:version,:enabled,enabled),settings=IF(version=:version,:settings,settings),status=IF(version=:version,:status,status),capabilities=IF(version=:version,NULL,capabilities),last_checked_at=IF(version=:version,NULL,last_checked_at),result_code=IF(version=:version,NULL,result_code),version=IF(version=:version,version+1,version),updated_at=CURRENT_TIMESTAMP(6)").param("owner",owner).param("kind",kind).param("provider",request.provider()).param("environment",request.environment()).param("enabled",request.enabled()).param("settings",encode(request.settings())).param("status",status).param("version",request.version()).update();if(changed==0)throw new AuthException(HttpStatus.CONFLICT,"INTEGRATION_VERSION_CONFLICT","Cấu hình đã thay đổi.");if(kind.equals("PAYMENT")){var legacy=new LinkedHashMap<String,Object>();for(String field:List.of("cashEnabled","bankTransferEnabled","bankName","bankBin","qrEnabled","accountName","accountNumber","transferContent"))if(request.settings().containsKey(field))legacy.put(field,request.settings().get(field));if(!legacy.isEmpty())settings.updateGroup(actor,"payments",new com.thangit.boardinghouse.dto.request.setting.AdminSettingRequests.UpdateGroup(legacy));}
        db.sql("INSERT INTO integration_operations(owner_id,kind,operation,request_key,provider,environment,status,result_code,actor_id,finished_at) VALUES(:owner,:kind,'CONFIG_SAVE',:key,:provider,:environment,:status,'CONFIGURATION_SAVED',:owner,CURRENT_TIMESTAMP(6))").param("owner",owner).param("kind",kind).param("key","version-"+(current.version()+1)).param("provider",request.provider()).param("environment",request.environment()).param("status",status).update();if(request.enabled()&&Set.of("EMAIL","ZALO","WEB_PUSH").contains(kind))rules.owner(owner);return view(owner,kind);
    }
    String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw invalid("INTEGRATION_JSON_INVALID");}}
    public Object history(AuthenticatedUser actor,String kind){long owner=owner(actor);kind(kind);return db.sql("SELECT id,kind,operation,status,result_code,provider_reference,created_at,finished_at FROM integration_operations WHERE owner_id=:owner AND kind=:kind ORDER BY id DESC LIMIT 100").param("owner",owner).param("kind",kind).query().listOfRows();}
    public Map<String,Object> execute(AuthenticatedUser actor,String kind,String operation,String key,TestRequest request){long owner=owner(actor);kind(kind);if(key==null||!key.matches("[a-zA-Z0-9:_-]{8,100}"))throw invalid("INTEGRATION_IDEMPOTENCY_REQUIRED");if(!Set.of("CHECK","TEST_SEND","SYNC_TEMPLATES","REFRESH_TOKEN").contains(operation))throw invalid("INTEGRATION_OPERATION_INVALID");var c=config(owner,kind);String payloadHash=WebPushSender.hash(encode(request));var existing=db.sql("SELECT id,status,result_code,provider_reference,payload_hash FROM integration_operations WHERE owner_id=:owner AND kind=:kind AND operation=:op AND request_key=:key").param("owner",owner).param("kind",kind).param("op",operation).param("key",key).query().listOfRows();if(!existing.isEmpty()){var old=existing.getFirst();if(old.get("payload_hash")!=null&&!payloadHash.equals(old.get("payload_hash")))throw invalid("INTEGRATION_IDEMPOTENCY_CONFLICT");return Map.of("status",old.get("status"),"resultCode",old.get("result_code"),"providerReference",Objects.toString(old.get("provider_reference"),""));}
        if(db.sql("SELECT COUNT(*) FROM integration_operations WHERE owner_id=:owner AND kind=:kind AND operation<>'CONFIG_SAVE' AND created_at>DATE_SUB(CURRENT_TIMESTAMP(6),INTERVAL 1 MINUTE)").param("owner",owner).param("kind",kind).query(Long.class).single()>=20)throw invalid("INTEGRATION_RATE_LIMIT_REACHED");
        int inserted=db.sql("INSERT IGNORE INTO integration_operations(owner_id,kind,operation,request_key,payload_hash,provider,environment,status,result_code,actor_id) VALUES(:owner,:kind,:op,:key,:payload,:provider,:environment,'TESTING','REQUEST_CREATED',:owner)").param("owner",owner).param("kind",kind).param("op",operation).param("key",key).param("payload",payloadHash).param("provider",c.provider()).param("environment",c.environment()).update();if(inserted==0)return Map.of("status","TESTING","resultCode","REQUEST_ALREADY_EXISTS");IntegrationAdapters.Outcome result;
        db.sql("UPDATE integration_configs SET status='TESTING' WHERE owner_id=:owner AND kind=:kind AND version=:version").param("owner",owner).param("kind",kind).param("version",c.version()).update();
        try{if(!c.enabled())result=new IntegrationAdapters.Outcome(c.status().equals("NOT_CONFIGURED")?"NOT_CONFIGURED":"DISABLED","INTEGRATION_DISABLED",null,Map.of());else if(!adapters.complete(c))result=new IntegrationAdapters.Outcome("NOT_CONFIGURED","CREDENTIAL_OR_CONFIGURATION_MISSING",null,Map.of());else {result=adapters.execute(c,operation,key,request);}}catch(AuthException failure){result=new IntegrationAdapters.Outcome("ERROR",failure.code().matches("[A-Z0-9_]{1,80}")?failure.code():"PROVIDER_REQUEST_FAILED",null,Map.of());}catch(Exception failure){result=new IntegrationAdapters.Outcome("ERROR","PROVIDER_REQUEST_FAILED",null,Map.of());}
        db.sql("UPDATE integration_operations SET status=:status,result_code=:code,provider_reference=:reference,finished_at=CURRENT_TIMESTAMP(6) WHERE owner_id=:owner AND kind=:kind AND operation=:op AND request_key=:key").param("status",result.status()).param("code",result.code()).param("reference",result.reference()).param("owner",owner).param("kind",kind).param("op",operation).param("key",key).update();String configStatus=Set.of("SENT","DELIVERED").contains(result.status())?"CONNECTED":Set.of("UNKNOWN","SIMULATED").contains(result.status())?"DEGRADED":result.status();db.sql("UPDATE integration_configs SET status=:status,capabilities=:capabilities,result_code=:code,last_checked_at=CURRENT_TIMESTAMP(6) WHERE owner_id=:owner AND kind=:kind AND version=:version").param("status",configStatus).param("capabilities",encode(result.capabilities())).param("code",result.code()).param("owner",owner).param("kind",kind).param("version",c.version()).update();return Map.of("status",result.status(),"resultCode",result.code(),"capabilities",result.capabilities(),"providerReference",Objects.toString(result.reference(),""));
    }
}
